solution.code:
function transpose(m) {
  var result = [];
  for (var j = 0; j < m[0].length; j++) {
    var row = [];
    for (var i = 0; i < m.length; i++) {
      row.push(m[i][j]);
    }
    result.push(row);
  }
  return result;
}

console.log(transpose([[1, 2, 3], [4, 5, 6]]));
